/**
 * Interpolates variables in subject and html template
 */
export function renderEmail(
  key: EmailTemplateKey,
  variables: Record<string, any> = {}
): { subject: string; html: string; title: string } {
  const tpl = EMAIL_TEMPLATES[key]
  if (!tpl) {
    throw new Error(`Email template not found for key: ${key}`)
  }

  const merged = { ...EMAIL_DEFAULT_VARS, ...variables }

  let subject = tpl.subject
  let html = tpl.html

  for (const [k, v] of Object.entries(merged)) {
    const regex = new RegExp(`\\{\\{${k}\\}\\}`, 'g')
    const stringVal = v === null || v === undefined ? '' : String(v)
    subject = subject.replace(regex, stringVal)
    html = html.replace(regex, stringVal)
  }

  // Clean any unresolved {{variables}} to empty strings
  subject = subject.replace(/\{\{[a-zA-Z0-9_]+\}\}/g, '')
  html = html.replace(/\{\{[a-zA-Z0-9_]+\}\}/g, '')

  return {
    subject,
    html,
    title: tpl.title,
  }
}
